+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int FIRST_NAME = 0;
+    private static final int LAST_NAME = 1;
+    private static final int SPECIALTIES = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinariansLinkOpensGridWithEveryVetAndTheirSpecialties() {
+        navigate(WelcomeView.class);
+
+        // SideNav routes on the client, so follow the item's path the way the browser would.
+        SideNavItem link = find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single();
+        UI.getCurrent().navigate(link.getPath());
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        GridTester<Grid<Object>, Object> grid = vetGrid();
+        assertEquals(6, grid.size());
+        assertRow(grid, 0, "James", "Carter", "none");
+        assertRow(grid, 1, "Linda", "Douglas", "dentistry, surgery");
+        assertRow(grid, 2, "Sharon", "Jenkins", "none");
+        assertRow(grid, 3, "Helen", "Leary", "radiology");
+        assertRow(grid, 4, "Rafael", "Ortega", "surgery");
+        assertRow(grid, 5, "Henry", "Stevens", "radiology");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsColumnHeaders() {
+        navigate(VetsView.class);
+
+        Grid<?> grid = find(Grid.class).single();
+        List<String> headers = grid.getColumns().stream().map(Grid.Column::getHeaderText).toList();
+        assertEquals(List.of("First Name", "Last Name", "Specialties"), headers);
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansRendersEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, vetGrid().size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void vetsAreFetchedLazilyInChunks() {
+        // Far more vets than one chunk, so the grid has to fetch several.
+        IntStream.rangeClosed(1, 120).forEach(i -> dsl.insertInto(VETS)
+                .set(VETS.FIRST_NAME, "First")
+                .set(VETS.LAST_NAME, String.format("Zz%03d", i))
+                .execute());
+
+        navigate(VetsView.class);
+
+        Grid<?> grid = find(Grid.class).single();
+        assertFalse(grid.getDataProvider().isInMemory(),
+                "Expected a callback data provider that fetches rows on demand");
+        GridTester<Grid<Object>, Object> tester = vetGrid();
+        assertEquals(126, tester.size());
+        assertRow(tester, 6, "First", "Zz001", "none");
+        assertRow(tester, 125, "First", "Zz120", "none");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetsView.class);
+
+        // Linda Douglas holds surgery (id 2) and dentistry (id 3): name order, not id order.
+        assertEquals("dentistry, surgery", vetGrid().getCellText(1, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansAreShownWithoutLogin() {
+        assertDoesNotThrow(() -> navigate(VetsView.class),
+                "Expected /vets to open without authentication");
+    }
+
+    @SuppressWarnings("unchecked")
+    private GridTester<Grid<Object>, Object> vetGrid() {
+        return test(find(Grid.class).single());
+    }
+
+    private static void assertRow(GridTester<Grid<Object>, Object> grid, int row,
+                                  String firstName, String lastName, String specialties) {
+        assertEquals(firstName, grid.getCellText(row, FIRST_NAME));
+        assertEquals(lastName, grid.getCellText(row, LAST_NAME));
+        assertEquals(specialties, grid.getCellText(row, SPECIALTIES));
+    }
+}
